import importlib
import json
import os
import sys
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
sys.path.insert(0, ROOT)

from notifykit.backend import Recorder
from notifykit.client import Client

CASES = [['app.alerts', 'quiet_send', '(["a", "ghost", "b"], "psst  ")', [None, [['deliver', 'a', 'psst', 'normal', None, 3], ['deliver', 'b', 'psst', 'normal', None, 3]]]], ['app.alerts', 'quiet_send', '([], "x")', [None, []]], ['app.alerts', 'send_digest', '("u1", ["a", "b"])', [True, [['deliver', 'u1', 'a; b', 'normal', None, 1]]]], ['app.alerts', 'send_digest', '("ghost", ["a"])', [False, []]], ['app.alerts', 'send_digest', '("u2", [])', [True, [['deliver', 'u2', '', 'normal', None, 1]]]], ['app.alerts', 'schedule_nudge', '("u7", "stand up ", 2)', ['m1', [['deliver', 'u7', 'stand up', 'normal', 120000, 1]]]], ['app.alerts', 'schedule_nudge', '("ghost", "x", 1)', [None, []]], ['app.alerts', 'schedule_nudge', '("u8", "half", 0.5)', ['m1', [['deliver', 'u8', 'half', 'normal', 30000, 1]]]]]


def norm(v):
    return json.loads(json.dumps(v, default=repr))


def run_case(modname, func, args_expr):
    rec = Recorder()
    pass
    client = Client(rec)
    mod = importlib.import_module(modname)
    args = eval(args_expr, {"rec": rec})
    factory = func.startswith(("make_", "open_", "connect", "attach", "build_"))
    try:
        ret = getattr(mod, func)(*args) if factory else getattr(mod, func)(client, *args)
    except Exception as ex:
        ret = "raises:" + type(ex).__name__
    if factory and type(ret).__name__ == "Client":
        ret = "client"
    return norm([ret, rec.events])


class MigrationTest(unittest.TestCase):
    def test_sites(self):
        bad = []
        for modname, func, args_expr, want in CASES:
            got = run_case(modname, func, args_expr)
            if got != want:
                bad.append("%s.%s%s -> %s, want %s" % (modname, func, args_expr, got, want))
        self.assertEqual(bad, [], "\n" + "\n".join(bad[:6]))

    def test_legacy_is_not_used(self):
        import ast
        for dirpath, _, names in os.walk(os.path.join(ROOT, "app")):
            for n in names:
                if n.endswith(".py"):
                    tree = ast.parse(open(os.path.join(dirpath, n), encoding="utf-8").read())
                    for node in ast.walk(tree):
                        if isinstance(node, (ast.Import, ast.ImportFrom)):
                            mod = getattr(node, "module", None) or ",".join(a.name for a in node.names)
                            self.assertNotIn("legacy_notify", mod, "%s still imports the legacy client" % n)


if __name__ == "__main__":
    unittest.main()

