"""Application code of the service."""
from notifykit.client import Client, DeliveryError, Message, Receipt


def quiet_send(client, users, text):
    for u in users:
        try:
            client.publish(Message(u, text.rstrip()))
        except DeliveryError:
            pass


def send_digest(client, user, lines):
    text = "; ".join(lines) + "\n"
    try:
        client.publish(Message(user, text.rstrip(), max_attempts=1))
    except DeliveryError:
        return False
    return True


def schedule_nudge(client, user, text, minutes):
    ttl = minutes * 60
    try:
        return client.publish(Message(user, text.rstrip(), expires_in_ms=int(ttl * 1000), max_attempts=1)).id
    except DeliveryError:
        return None

