"""Application code of the service."""


def quiet_send(notifier, users, text):
    for u in users:
        notifier.notify(u, text)


def send_digest(notifier, user, lines):
    text = "; ".join(lines) + "\n"
    ok, _ = notifier.notify(user, text, retry=False)
    return ok


def schedule_nudge(notifier, user, text, minutes):
    ok, ref = notifier.notify(user, text, ttl_s=minutes * 60, retry=False)
    return ref if ok else None

