from notifykit.client import Client, DeliveryError, Message, Receipt


def nudge(client, user, text, minutes):
    ttl = minutes * 60
    try:
        return client.publish(Message(user, text.rstrip(), expires_in_ms=int(ttl * 1000), max_attempts=1)).id
    except DeliveryError:
        return None


def broadcast(client, users, text):
    results = client.publish_all([Message(u, text.rstrip(), priority="normal") for u in users])
    sent = len([r for r in results if isinstance(r, Receipt)])
    failed = [u for u, r in zip(users, results) if isinstance(r, DeliveryError)]
    return sent, failed

